import hashlib
import math

class BloomFilter:
    """
    A Bloom Filter implementation that efficiently determines whether an item is in a set.
    The filter uses bit array and multiple hash functions to achieve a configurable false positive rate.

    Parameters:
    - expected_items: int - The expected number of items to be added to the filter.
    - false_positive_rate: float - The desired maximum false positive rate.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        if expected_items <= 0:
            raise ValueError("Expected items must be greater than 0.")
        if not (0 < false_positive_rate < 1):
            raise ValueError("False positive rate must be between 0 and 1.")

        self.num_bits = self._get_optimal_bit_array_size(expected_items, false_positive_rate)
        self.num_hashes = self._get_optimal_num_hash_functions(self.num_bits, expected_items)
        self.bit_array = [0] * self.num_bits

    def _get_optimal_bit_array_size(self, expected_items: int, false_positive_rate: float) -> int:
        """Calculate the optimal bit array size."""
        return math.ceil((-expected_items * math.log(false_positive_rate)) / (math.log(2) ** 2))

    def _get_optimal_num_hash_functions(self, num_bits: int, expected_items: int) -> int:
        """Calculate the optimal number of hash functions."""
        return max(1, int((num_bits / expected_items) * math.log(2)))

    def _hash(self, item: str, seed: int) -> int:
        """Create a hash of the item with a given seed."""
        hash_result = hashlib.md5((str(seed) + item).encode()).hexdigest()
        return int(hash_result, 16) % self.num_bits

    def add(self, item: str) -> None:
        """Add an item to the bloom filter."""
        for i in range(self.num_hashes):
            index = self._hash(item, i)
            self.bit_array[index] = 1

    def contains(self, item: str) -> bool:
        """Check if an item is possibly in the filter."""
        for i in range(self.num_hashes):
            index = self._hash(item, i)
            if self.bit_array[index] == 0:
                return False
        return True

