    def _calculate_number_of_hashes(self) -> int:
        """Calculate the optimal number of hash functions to use."""
        return max(1, int((self.size / self.expected_items) * math.log(2)))

    def _hash(self, item: str, seed: int) -> int:
        """Generate a hash value using the item and a given seed."""
        hashed = hashlib.md5((str(seed) + item).encode()).hexdigest()
