import hashlib
import math

class BloomFilter:
    """
    A Bloom Filter implementation to efficiently test membership of a set of items with a controllable false-positive rate.

    The class calculates the optimal size of the bit array and the number of hash functions based on the expected number 
    of items and the desired false positive rate. Hashing is done using the built-in hashlib library.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        self.num_bits = self._calculate_bit_array_size(expected_items, false_positive_rate)
        self.num_hashes = self._calculate_number_of_hashes(self.num_bits, expected_items)
        self.bit_array = [0] * self.num_bits

    def _calculate_bit_array_size(self, n: int, p: float) -> int:
        """Calculates the optimal size of the bit array."""
        m = -n * math.log(p) / (math.log(2) ** 2)
        return int(math.ceil(m))

    def _calculate_number_of_hashes(self, m: int, n: int) -> int:
        """Calculates the optimal number of hash functions."""
        k = (m / n) * math.log(2)
        return int(math.ceil(k))

    def _hashes(self, item: str) -> list:
        """Generates hash values for the item using multiple hash functions."""
        hash_values = []
        for i in range(self.num_hashes):
            hash_value = int(hashlib.md5(f"{item}{i}".encode('utf-8')).hexdigest(), 16) % self.num_bits
            hash_values.append(hash_value)
        return hash_values

    def add(self, item: str) -> None:
        """Adds an item to the Bloom filter."""
        for idx in self._hashes(item):
            self.bit_array[idx] = 1

    def contains(self, item: str) -> bool:
        """Checks if an item is in the Bloom filter."""
        return all(self.bit_array[idx] for idx in self._hashes(item))

import hashlib
import math

class BloomFilter:
    """
    A Bloom Filter implementation that uses a bit array to efficiently test
    set membership while allowing for false positives. The filter's size and 
    number of hash functions are calculated based on the expected number of 
    items and the desired false positive rate.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        # Calculate the optimal size of the bit array
        self.size = self._optimal_size(expected_items, false_positive_rate)

        # Calculate the optimal number of hash functions
        self.hash_count = self._optimal_hash_count(self.size, expected_items)

        # Create a bit array initialized to 0
        self.bit_array = 0

    def _optimal_size(self, n: int, p: float) -> int:
        """Calculate the optimal size of the bit array."""
        return math.ceil(-n * math.log(p) / (math.log(2) ** 2))

    def _optimal_hash_count(self, m: int, n: int) -> int:
        """Calculate the optimal number of hash functions."""
        return math.ceil((m / n) * math.log(2))

    def _hashes(self, item: str) -> list:
        """Generate the hash values for an item."""
        hash_values = []
        item_bytes = item.encode('utf-8')
        for i in range(self.hash_count):
            hash_value = int(hashlib.md5(item_bytes + i.to_bytes(2, 'big')).hexdigest(), 16)
            hash_values.append(hash_value % self.size)
        return hash_values

    def add(self, item: str) -> None:
        """Add an item to the Bloom filter."""
        for hash_value in self._hashes(item):
            self.bit_array |= (1 << hash_value)

    def contains(self, item: str) -> bool:
        """Check if an item is possibly in the Bloom filter."""
        for hash_value in self._hashes(item):
            if not (self.bit_array & (1 << hash_value)):
                return False
        return True
